    // variables.  In particular FOR-IN structures must not be modified.
    if (NodeUtil.isLoopStructure(n)) {
      return;
    }

    // For all VARs
    if (NodeUtil.isVar(n)) {
      Node name = n.getFirstChild();
      // It isn't initialized.
